using Aspire.Hosting.Testing;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.DependencyInjection;

namespace MyApp.Evaluation;

[TestClass]
public class ChatEvaluationTests
{
    private static DistributedApplicationTestingBuilder _appHost = null!;
    private static ReportingConfiguration? _reportingConfiguration;

    [ClassInitialize]
    public static async Task ClassInitialize(TestContext context)
    {
        _appHost = await DistributedApplicationTestingBuilder.CreateAsync<Projects.MyApp_AppHost>();
        await _appHost.BuildAsync();

        _reportingConfiguration = CreateReportingConfiguration();
    }

    [ClassCleanup]
    public static async Task ClassCleanup()
    {
        if (_appHost is not null)
        {
            await _appHost.DisposeAsync();
        }
    }

    [TestMethod]
    public async Task Chat_ResponseRelevance()
    {
        await using var scenario = await _reportingConfiguration!.CreateScenarioRunAsync(
            scenarioName: nameof(Chat_ResponseRelevance));

        var chatClient = GetChatClient();

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is the capital of France?")
        };

        var response = await chatClient.GetResponseAsync(messages);
        messages.Add(response.Message);

        await scenario.EvaluateAsync(messages);
    }

    [TestMethod]
    public async Task Chat_ResponseCoherence()
    {
        await using var scenario = await _reportingConfiguration!.CreateScenarioRunAsync(
            scenarioName: nameof(Chat_ResponseCoherence));

        var chatClient = GetChatClient();

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Explain how photosynthesis works in two sentences.")
        };

        var response = await chatClient.GetResponseAsync(messages);
        messages.Add(response.Message);

        await scenario.EvaluateAsync(messages);
    }

    [TestMethod]
    public async Task Chat_MultiTurnConversation()
    {
        await using var scenario = await _reportingConfiguration!.CreateScenarioRunAsync(
            scenarioName: nameof(Chat_MultiTurnConversation));

        var chatClient = GetChatClient();

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What are three primary colors?")
        };

        var response = await chatClient.GetResponseAsync(messages);
        messages.Add(response.Message);

        messages.Add(new ChatMessage(ChatRole.User, "Now name a color you get by mixing the first two."));

        response = await chatClient.GetResponseAsync(messages);
        messages.Add(response.Message);

        await scenario.EvaluateAsync(messages);
    }

    private static IChatClient GetChatClient()
    {
        var app = _appHost.Services.GetRequiredService<DistributedApplication>();
        return app.Services.GetRequiredService<IChatClient>();
    }

    private static ReportingConfiguration CreateReportingConfiguration()
    {
        var evaluators = new IEvaluator[]
        {
            new RelevanceEvaluator(),
            new CoherenceEvaluator(),
            new FluencyEvaluator()
        };

        return new ReportingConfiguration(
            storageRootPath: Path.Combine(
                Path.GetTempPath(), "MyApp.Evaluation", "reports"),
            evaluators: evaluators);
    }
}

